//! Governed instrument-action planning for Worldgen P11 F01-F04.
use std::collections::{BTreeMap,BTreeSet};
use bioprism_foundation::{PRECLINICAL_BOUNDARY,RESEARCH_CONTRACT_SCHEMA_VERSION};
use bioprism_ids::ContentHash;
use serde::{Deserialize,Serialize};
use serde_json::json;
use thiserror::Error;
pub const CONTENT_TYPE:&str="application/vnd.aurora.worldgen.laboratory-integration-receipt+json";
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct InstrumentAction{pub action_id:String,pub instrument_id:String,pub operation:String,pub modality:String,pub interlock_order:Vec<String>,pub signed_preflight:bool,pub operator_authorized:bool,pub effect_tier:u8,pub evidence_state:String,pub evidence_digest:ContentHash,pub provenance_digest:ContentHash,pub artifact_digest:ContentHash,pub replay_identity:ContentHash,pub permitted:bool,pub raw_data_local:bool,pub negative_result:bool,pub boundary:String}
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct InstrumentActionRequest{pub request_id:String,pub study_id:String,pub purpose:String,pub semantic_profile:String,pub required_action_order:Vec<String>,pub action_order:Vec<String>,pub actions:Vec<InstrumentAction>,pub replay_identity:ContentHash,pub policy_allow:bool,pub protected_closure:bool,pub federation_approved:bool,pub raw_data_local:bool,pub aggregate_only:bool,pub emergency_stop:bool,pub boundary:String}
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct InstrumentActionReceipt{pub schema_version:String,pub contract_version:String,pub feature_id:String,pub request_id:String,pub study_id:String,pub purpose:String,pub semantic_profile:String,pub disposition:String,pub required_action_order:Vec<String>,pub action_order:Vec<String>,pub admitted_action_order:Vec<String>,pub unresolved_action_order:Vec<String>,pub blocked_action_order:Vec<String>,pub omitted_action_order:Vec<String>,pub interlock_order:Vec<String>,pub failure_order:Vec<String>,pub omissions:Vec<String>,pub uncertainty:Vec<String>,pub contradiction:Vec<String>,pub negative_evidence:Vec<String>,pub replay_identity:ContentHash,pub receipt_digest:ContentHash,pub effect_receipts:Vec<String>,pub artifact:serde_json::Value,pub raw_data_local:bool,pub aggregate_only:bool,pub boundary:String}
#[derive(Debug,Error,Clone,PartialEq,Eq)]pub enum LaboratoryIntegrationError{#[error("invalid laboratory integration request: {0}")]Invalid(String),#[error("laboratory integration artifact failed: {0}")]Artifact(String),#[error("invalid laboratory integration receipt: {0}")]Receipt(String)}
fn h(v:&ContentHash)->bool{v.as_str().len()==64&&v.as_str().bytes().all(|b|b.is_ascii_hexdigit())}fn o(v:&[String])->bool{v.windows(2).all(|p|p[0]<p[1])}fn s(mut v:Vec<String>)->Vec<String>{v.sort();v.dedup();v}
impl InstrumentActionReceipt{pub fn validate(&self)->Result<(),LaboratoryIntegrationError>{if self.schema_version!=RESEARCH_CONTRACT_SCHEMA_VERSION||self.boundary!=PRECLINICAL_BOUNDARY||self.artifact.get("boundary").and_then(|v|v.as_str())!=Some(PRECLINICAL_BOUNDARY)||self.artifact.get("content_type").and_then(|v|v.as_str())!=Some(CONTENT_TYPE)||!self.raw_data_local||!self.aggregate_only||self.request_id.trim().is_empty()||self.study_id.trim().is_empty()||self.purpose.trim().is_empty()||self.action_order.is_empty()||self.effect_receipts.is_empty()||![&self.replay_identity,&self.receipt_digest].into_iter().all(h){return Err(LaboratoryIntegrationError::Receipt("instrument identity, actions, locality, digests, or effects are incomplete".into()));}for v in [&self.required_action_order,&self.action_order,&self.admitted_action_order,&self.unresolved_action_order,&self.blocked_action_order,&self.omitted_action_order,&self.interlock_order,&self.failure_order,&self.omissions,&self.uncertainty,&self.contradiction,&self.negative_evidence,&self.effect_receipts]{if !o(v){return Err(LaboratoryIntegrationError::Receipt("instrument vectors are not canonical".into()));}}let ids=self.action_order.iter().cloned().collect::<BTreeSet<_>>();let parts=self.admitted_action_order.iter().chain(&self.unresolved_action_order).chain(&self.blocked_action_order).chain(&self.omitted_action_order).cloned().collect::<Vec<_>>();if ids.len()!=self.action_order.len()||parts.len()!=ids.len()||parts.iter().cloned().collect::<BTreeSet<_>>()!=ids{return Err(LaboratoryIntegrationError::Receipt("instrument action states do not partition".into()));}if self.artifact.get("content_hash").and_then(|v|v.as_str())!=Some(self.receipt_digest.as_str()){return Err(LaboratoryIntegrationError::Receipt("instrument artifact digest is inconsistent".into()));}if self.effect_receipts.iter().any(|e|e!="block:unsafe-release"&&!e.starts_with("preflight:worldgen-instrument:")){return Err(LaboratoryIntegrationError::Receipt("instrument effect is outside preflight gate".into()));}Ok(())}}
pub fn manifest(feature_id:&str,version:&str,input_schema:&str,scale:&str,autonomy:&str)->serde_json::Value{json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"capability_id":feature_id,"version":version,"owner_crate":"worldgen","consumers":["preclinical neuroscientist","bioinformatician","imaging core scientist","research program lead"],"behavior":format!("preflight governed instrument actions for {scale}"),"value":"binds instrument capabilities to signed interlocks, human authorization, emergency stops, provenance, and no-implicit-execution effects","input_schema":input_schema,"output_schema":"InstrumentActionReceipt1@1","effects":["preflight:worldgen-instrument","block:unsafe-release"],"permissions":["preflight:instrument-action"],"determinism":"byte_stable","autonomy_tier":autonomy,"boundary":PRECLINICAL_BOUNDARY,"contract_version":version})}
pub fn integrate(request:&InstrumentActionRequest,feature_id:&str,version:&str,scale:&str,require_federation:bool)->Result<InstrumentActionReceipt,LaboratoryIntegrationError>{if request.request_id.trim().is_empty()||request.study_id.trim().is_empty()||request.purpose.trim().is_empty()||request.semantic_profile.trim().is_empty()||request.required_action_order.is_empty()||request.action_order.is_empty()||request.action_order!=s(request.action_order.clone())||request.required_action_order!=s(request.required_action_order.clone())||request.boundary!=PRECLINICAL_BOUNDARY||!request.raw_data_local||!request.aggregate_only||!h(&request.replay_identity){return Err(LaboratoryIntegrationError::Invalid("instrument identity, ordering, locality, boundary, or replay is invalid".into()));}if require_federation&&!request.federation_approved{return Err(LaboratoryIntegrationError::Invalid("instrument federation approval is required".into()));}let ids=request.action_order.iter().cloned().collect::<BTreeSet<_>>();let mut by_id=BTreeMap::new();for a in &request.actions{if !ids.contains(&a.action_id)||a.instrument_id.trim().is_empty()||a.operation.trim().is_empty()||a.modality.trim().is_empty()||a.boundary!=PRECLINICAL_BOUNDARY||!a.raw_data_local||a.replay_identity!=request.replay_identity||a.effect_tier>4||a.interlock_order.is_empty()||!h(&a.evidence_digest)||!h(&a.provenance_digest)||!h(&a.artifact_digest)||!h(&a.replay_identity){return Err(LaboratoryIntegrationError::Invalid("instrument action identity, interlocks, provenance, locality, replay, or boundary is invalid".into()));}if by_id.insert(a.action_id.clone(),a).is_some(){return Err(LaboratoryIntegrationError::Invalid("duplicate instrument action".into()));}}
let mut admitted=Vec::new();let mut unresolved=BTreeSet::new();let mut blocked=BTreeSet::new();let mut omitted=BTreeSet::new();let mut interlocks=BTreeSet::new();let mut failures=BTreeSet::new();let mut omissions=BTreeSet::new();let mut uncertainty=BTreeSet::new();let mut contradiction=BTreeSet::new();let mut negative=BTreeSet::new();for id in &ids{match by_id.get(id){None=>{omitted.insert(id.clone());omissions.insert(format!("action:{}:missing",id));},Some(a)if request.emergency_stop=>{blocked.insert(id.clone());failures.insert(format!("action:{}:emergency-stop",id));omissions.insert(format!("action:{}:emergency-stop-active",id));},Some(a)if !request.policy_allow||!request.protected_closure||!a.permitted=>{blocked.insert(id.clone());failures.insert(format!("action:{}:policy-or-permission-denied",id));omissions.insert(format!("action:{}:policy-or-permission-blocked",id));},Some(a)if a.effect_tier>=3&&(!a.signed_preflight||!a.operator_authorized)=>{blocked.insert(id.clone());failures.insert(format!("action:{}:signed-preflight-or-operator-authorization-required",id));},Some(a)if a.negative_result=>{unresolved.insert(id.clone());negative.insert(format!("action:{}:negative-result-retained",id));interlocks.extend(a.interlock_order.iter().cloned());},Some(a)if a.evidence_state=="contradicted"=>{unresolved.insert(id.clone());contradiction.insert(format!("action:{}:contradicted",id));interlocks.extend(a.interlock_order.iter().cloned());},Some(a)if a.evidence_state=="unknown"||a.evidence_state=="unmeasured"=>{unresolved.insert(id.clone());uncertainty.insert(format!("action:{}:{}",id,a.evidence_state));interlocks.extend(a.interlock_order.iter().cloned());},Some(a)=>{interlocks.extend(a.interlock_order.iter().cloned());admitted.push(a);}}}admitted.sort_by(|a,b|a.action_id.cmp(&b.action_id));let admitted_ids=admitted.iter().map(|a|a.action_id.clone()).collect::<BTreeSet<_>>();let authority=request.policy_allow&&request.protected_closure&&!request.emergency_stop&&(!require_federation||request.federation_approved);let disposition=if !authority{"blocked"}else if admitted.is_empty(){"unknown"}else if admitted_ids.len()==ids.len()&&omissions.is_empty()&&unresolved.is_empty()&&blocked.is_empty(){"qualified"}else{"partial"};let effects=if disposition=="blocked"{vec!["block:unsafe-release".into()]}else{vec![format!("preflight:worldgen-instrument:{}",request.study_id)]};let payload=json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"contract_version":version,"feature_id":feature_id,"request_id":request.request_id,"study_id":request.study_id,"purpose":request.purpose,"semantic_profile":request.semantic_profile,"scale":scale,"disposition":disposition,"required_action_order":request.required_action_order,"action_order":ids,"admitted_action_order":admitted_ids,"unresolved_action_order":unresolved,"blocked_action_order":blocked,"omitted_action_order":omitted,"interlock_order":interlocks,"failure_order":failures,"omissions":omissions,"uncertainty":uncertainty,"contradiction":contradiction,"negative_evidence":negative,"replay_identity":request.replay_identity,"effect_receipts":effects,"raw_data_local":true,"aggregate_only":true,"boundary":PRECLINICAL_BOUNDARY});let d=ContentHash::of_value(&payload).map_err(|e|LaboratoryIntegrationError::Artifact(e.to_string()))?;let r=InstrumentActionReceipt{schema_version:RESEARCH_CONTRACT_SCHEMA_VERSION.into(),contract_version:version.into(),feature_id:feature_id.into(),request_id:request.request_id.clone(),study_id:request.study_id.clone(),purpose:request.purpose.clone(),semantic_profile:request.semantic_profile.clone(),disposition:disposition.into(),required_action_order:request.required_action_order.clone(),action_order:ids.iter().cloned().collect(),admitted_action_order:admitted_ids.iter().cloned().collect(),unresolved_action_order:unresolved.into_iter().collect(),blocked_action_order:blocked.into_iter().collect(),omitted_action_order:omitted.into_iter().collect(),interlock_order:interlocks.into_iter().collect(),failure_order:failures.into_iter().collect(),omissions:omissions.into_iter().collect(),uncertainty:uncertainty.into_iter().collect(),contradiction:contradiction.into_iter().collect(),negative_evidence:negative.into_iter().collect(),replay_identity:request.replay_identity.clone(),receipt_digest:d.clone(),effect_receipts:effects,artifact:json!({"artifact_id":format!("worldgen-instrument-preflight:{}",request.study_id),"content_type":CONTENT_TYPE,"content_hash":d,"boundary":PRECLINICAL_BOUNDARY}),raw_data_local:true,aggregate_only:true,boundary:PRECLINICAL_BOUNDARY.into()};r.validate()?;Ok(r)}
#[cfg(test)]mod tests{use super::*;fn h(v:&str)->ContentHash{ContentHash::of_bytes(v.as_bytes())}fn req()->InstrumentActionRequest{let r=h("replay");let a=InstrumentAction{action_id:"action:a".into(),instrument_id:"microscope:1".into(),operation:"acquire".into(),modality:"imaging".into(),interlock_order:vec!["door-closed".into()],signed_preflight:true,operator_authorized:true,effect_tier:1,evidence_state:"supported".into(),evidence_digest:h("e"),provenance_digest:h("p"),artifact_digest:h("a"),replay_identity:r.clone(),permitted:true,raw_data_local:true,negative_result:false,boundary:PRECLINICAL_BOUNDARY.into()};InstrumentActionRequest{request_id:"req:a".into(),study_id:"study:a".into(),purpose:"preflight".into(),semantic_profile:"preclinical-neural".into(),required_action_order:vec!["action:a".into()],action_order:vec!["action:a".into()],actions:vec![a],replay_identity:r,policy_allow:true,protected_closure:true,federation_approved:true,raw_data_local:true,aggregate_only:true,emergency_stop:false,boundary:PRECLINICAL_BOUNDARY.into()}}#[test]fn signed_action_is_preflighted(){let r=integrate(&req(),"AFA-worldgen-P11-F01","worldgen-local-laboratory-integration/1.0","local single-study",false).unwrap();assert_eq!(r.disposition,"qualified");assert_eq!(r.admitted_action_order,vec!["action:a"])}#[test]fn emergency_stop_blocks(){let mut q=req();q.emergency_stop=true;let r=integrate(&q,"AFA-worldgen-P11-F02","worldgen-multimodal-laboratory-integration/1.0","multimodal multi-study",false).unwrap();assert_eq!(r.disposition,"blocked");assert!(!r.failure_order.is_empty())}}
